def max_happiness(n: int, m: int, items) -> int:
    if m == 0 or n < 0:
        return 0

    # Create a 2D DP table
    # dp[i][j] = max importance using first i items with budget j
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    for i in range(1, m + 1):
        price, value = items[i - 1]
        for j in range(1, n + 1):
            # Option 1: Don't take item i
            dp[i][j] = dp[i - 1][j]
            # Option 2: Take item i if budget allows
            if j >= price:
                dp[i][j] = max(dp[i][j], dp[i - 1][j - price] + value)

    return dp[m][n]

def polynomial_to_string(n: int, coeffs: list) -> str:
    if not coeffs:
        return "0"

    # Handle the case where all coefficients are zero
    if all(c == 0 for c in coeffs):
        return "0"

    terms = []
    for i, coeff in enumerate(coeffs):
        if coeff == 0:
            continue

        degree = n - i

        # Determine the sign
        if coeff < 0:
            sign = "-"
            abs_coeff = -coeff
        else:
            sign = "+" if terms else ""
            abs_coeff = coeff

        # Determine the coefficient part
        if degree > 0 and abs_coeff == 1:
            coeff_part = ""
        else:
            coeff_part = str(abs_coeff)

        # Determine the variable part
        if degree > 1:
            var_part = f"x^{degree}"
        elif degree == 1:
            var_part = "x"
        else:
            var_part = ""

        term = sign + coeff_part + var_part
        terms.append(term)

    return "".join(terms)

def select_volunteers(n: int, m: int, applicants: List[Tuple[int, int]]) -> Tuple[int, List[Tuple[int, int]]]:
