    if interview_count == 0:
        return (0, [])

    # The cutoff is the score of the last selected applicant
    cutoff = sorted_applicants[interview_count - 1][1]

    # Include all applicants with score >= cutoff, sorted properly
    qualified = []
    for app in sorted_applicants:
