def is_prime(num: int) -> bool:
    # Handle edge cases for numbers less than or equal to 1
    if num <= 1:
        return False
    # Small primes 2 and 3 are prime
    if num <= 3:
        return True
    # Check divisibility by 2 and 3
    if num % 2 == 0 or num % 3 == 0:
        return False
    # 6k +/- 1 optimization: all primes > 3 are of the form 6k-1 or 6k+1
    # We only need to check factors up to the square root of num
    i = 5
    while i * i <= num:
        if num % i == 0 or num % (i + 2) == 0:
            return False
        i += 6
    return True

def calculate_score(system: int, points: str) -> list:
    """
    Calculate the score of a series of ping-pong games based on the provided scoring system.

    :param system: The number of points required to win a game (either 11 or 21).
    :param points: A string of 'W' and 'L' characters denoting points won by the player and opponent.
    :return: A list of strings representing the score of each game.
    """
    # Validate the system
    if system not in (11, 21):
        raise ValueError("Scoring system must be either 11 or 21.")

    # Validate the points string
    if not all(c in 'WL' for c in points):
        raise ValueError("Points string must contain only 'W' and 'L' characters.")

    scores = []
    player_score = 0
    opponent_score = 0

    def is_game_over():
        """Check if the game is over with the required lead."""
        if player_score >= system and player_score - opponent_score >= 2:
            return True
        if opponent_score >= system and opponent_score - player_score >= 2:
            return True
        return False

    for point in points:
        if point == 'W':
            player_score += 1
        elif point == 'L':
            opponent_score += 1

        if is_game_over():
            scores.append(f"{player_score}:{opponent_score}")
            player_score = 0
            opponent_score = 0

    # If the sequence ends in the middle of a game, include the current score
    if player_score > 0 or opponent_score > 0:
        scores.append(f"{player_score}:{opponent_score}")

    return scores

def catalan_number(n: int) -> int:
    if n < 0:
        raise ValueError("n must be a non-negative integer")

    if n == 0:
        return 1

    catalan = [0] * (n + 1)
    catalan[0] = 1

    for i in range(1, n + 1):
        for j in range(i):
            catalan[i] += catalan[j] * catalan[i - j - 1]

    return catalan[n]

